// Canonical Wazuh alert (docs/WAZUH-FIELDS.md). Required fields missing or
// mistyped -> malformed. The alert id stays a string end to end.
const input = $input.first().json;
const alert = input.alert;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' && v.trim() !== '' ? v : null);
const opt = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : typeof v === 'number' ? String(v) : null);
const problems = [];
const a = isObj(alert) ? alert : {};
if (!isObj(alert)) problems.push('alert is not a JSON object');
const id = str(a.id);
if (!id) problems.push(typeof a.id === 'number' ? 'id is a number (digits may be lost), expected a string' : 'id missing');
const rule = isObj(a.rule) ? a.rule : null;
const agent = isObj(a.agent) ? a.agent : null;
let ruleId = null;
let level = null;
if (!rule) {
  problems.push('rule missing');
} else {
  ruleId = typeof rule.id === 'string' && rule.id.trim() !== '' ? rule.id.trim()
    : Number.isInteger(rule.id) ? String(rule.id) : null;
  if (!ruleId) problems.push('rule.id missing');
  if (typeof rule.level === 'number' && Number.isInteger(rule.level)) level = rule.level;
  else if (typeof rule.level === 'string' && /^\d+$/.test(rule.level.trim())) level = Number(rule.level.trim());
  else problems.push('rule.level missing or not numeric');
  if (!str(rule.description)) problems.push('rule.description missing');
  if (!Array.isArray(rule.groups) || !rule.groups.every((g) => typeof g === 'string')) {
    problems.push('rule.groups missing or not an array of strings');
  }
}
if (!agent || !str(agent.id) || !str(agent.name)) problems.push('agent.id / agent.name missing');
const ts = str(a.timestamp);
const dateMs = ts ? Date.parse(ts) : NaN;
if (!ts || Number.isNaN(dateMs)) problems.push('timestamp missing or unparseable');

if (problems.length > 0) {
  return [{ json: {
    ok: false,
    error_class: 'malformed_input',
    problems,
    wazuh_alert_id: id ?? (a.id === undefined || a.id === null ? null : String(a.id)),
    context: input.context ?? {},
    alert: alert === undefined ? null : alert,
  } }];
}

const d = isObj(a.data) ? a.data : {};
const sc = isObj(a.syscheck) ? a.syscheck : {};
const mitreId = isObj(rule.mitre) ? rule.mitre.id : undefined;
const mitre = Array.isArray(mitreId) ? mitreId.filter((t) => typeof t === 'string' && t !== '')
  : typeof mitreId === 'string' && mitreId !== '' ? [mitreId] : [];
return [{ json: { ok: true, canonical: {
  wazuh_alert_id: id,
  timestamp: ts,
  date_ms: dateMs,
  date_iso: new Date(dateMs).toISOString(),
  rule: {
    id: ruleId,
    id_int: /^\d+$/.test(ruleId) ? Number.parseInt(ruleId, 10) : null,
    level,
    description: rule.description,
    groups: rule.groups,
    firedtimes: typeof rule.firedtimes === 'number' ? rule.firedtimes : null,
    mitre_ids: mitre,
  },
  agent: { id: agent.id, name: agent.name, ip: opt(agent.ip) },
  manager_name: opt(a.manager?.name),
  location: opt(a.location),
  decoder_name: opt(a.decoder?.name),
  full_log: typeof a.full_log === 'string' && a.full_log !== '' ? a.full_log : null,
  network: {
    srcip: opt(d.srcip), dstip: opt(d.dstip), src_ip: opt(d.src_ip), dest_ip: opt(d.dest_ip),
    dest_port: opt(d.dest_port), srcuser: opt(d.srcuser), dstuser: opt(d.dstuser),
    hostname: opt(d.hostname), url: opt(d.url),
  },
  syscheck: {
    path: opt(sc.path), event: opt(sc.event), md5_after: opt(sc.md5_after),
    sha1_after: opt(sc.sha1_after), sha256_after: opt(sc.sha256_after),
  },
  virustotal_sha256: opt(d.virustotal?.source?.sha256),
} } }];

// Malformed input: lib-error parks it with the whole payload (N8N-1.2).
const j = $input.first().json;
return [{ json: {
  error_class: 'malformed_input',
  stage: 'normalize',
  workflow: $workflow.name,
  execution_id: j.context?.n8n_execution_id ?? $execution.id,
  sub_execution_id: $execution.id,
  node: 'Validate and normalize',
  wazuh_alert_id: j.wazuh_alert_id,
  thehive_alert_id: null,
  message: 'malformed Wazuh alert: ' + j.problems.join('; '),
  payload: j.alert,
} }];
